id;grid-template-columns:repeat(3,1fr);gap:14px}.card{border:1px solid var(--line);background:linear-gradient(180deg,rgba(255,255,255,.03),rgba(255,255,255,.012));border-radius:var(--r);padding:20px}.card img{width:38px;height:38px;object-fit:contain;margin-bottom:13px}.card h3{font:700 19px Outfit;margin:0 0 6px}.card p{font-size:13px;color:var(--muted);line-height:1.6;margin:0}.endpoint{border:1px solid var(--line);background:var(--card2);border-radius:16px;margin:12px 0;overflow:hidden}.ephead{padding:14px 16px;border-bottom:1px solid var(--line);display:flex;gap:10px;align-items:center;flex-wrap:wrap}.method{font-size:10px;font-weight:800;color:var(--ok);background:rgba(53,211,154,.08);padding:5px 7px;border-radius:6px}.url{font:600 13px ui-monospace,monospace;word-break:break-all}.epbody{padding:14px 16px;color:var(--muted);font-size:13px}.tester{display:grid;grid-template-columns:330px 1fr;gap:16px}.form{border:1px solid var(--line);background:var(--card);border-radius:18px;padding:18px}.form label{display:block;color:#c9ced8;font-size:12px;font-weight:700;margin:0 0 6px}.form input,.form select{width:100%;background:#080b10;border:1px solid var(--line);color:#fff;border-radius:10px;padding:11px;margin-bottom:12px;outline:none}.form input:focus,.form select:focus{border-color:#ef2147}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.preview{border:1px solid var(--line);background:#000;border-radius:18px;overflow:hidden;min-height:360px}.preview iframe{width:100%;height:520px;border:0;display:block;background:#000}.preview .empty{height:100%;min-height:360px;display:grid;place-items:center;color:#667080;padding:30px;text-align:center}.codebox{background:#07090d;border:1px solid var(--line);border-radius:14px;padding:15px;overflow:auto;font:12px/1.6 ui-monospace,monospace;color:#cbd3df}.notice{border:1px solid rgba(53,211,154,.2);background:rgba(53,211,154,.045);padding:16px;border-radius:15px;color:#b9c7c1}.notice strong{color:#fff}.footer{margin-top:40px;padding:30px 0 42px;border-top:1px solid var(--line);color:#707988;text-align:center}.footer b{color:#fff}@media(max-width:800px){.links{display:none}.cards{grid-template-columns:1fr}.tester{grid-template-columns:1fr}.preview iframe{height:62vh;min-height:400px}}@media(max-width:480px){.wrap{width:min(100% - 20px,1160px)}.hero{padding:55px 0 30px}.lead{font-size:14px}.section{padding:28px 0}.section h2{font-size:26px}.preview iframe{height:56vh;min-height:330px}.row{grid-template-columns:1fr}}
